import React, { useMemo, useRef } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
// Font Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@300;400;600`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema ---


export type MeditatingWavesProps = Record<string, any>;

// --- Subcomponents ---

// 1. Moving Wave Ribbon
const WaveRibbon: React.FC<{
  index: number;
  baseX: number;
  widthProp: number;
  color: string;
  speed: number;
  height: number;
  phaseShift: number;
  amplitude: number;
}> = ({ index, baseX, widthProp, color, speed, height, phaseShift, amplitude }) => {
  const frame = useCurrentFrame();
  
  // Create organic movement using sine waves
  const t = frame * 0.02 * speed;
  
  // Calculate dynamic control points
  const sway1 = Math.sin(t + phaseShift) * amplitude;
  const sway2 = Math.cos(t * 0.7 + phaseShift * 2) * (amplitude * 1.2);

  // Top and bottom positions
  const topX = baseX + sway1 * 0.5;
  const bottomX = baseX + sway2 * 0.5;
  
  // Control points for Bezier curve
  const cp1x = baseX + sway1 + amplitude; 
  const cp1y = height * 0.3;
  
  const cp2x = baseX + sway2 - amplitude;
  const cp2y = height * 0.7;

  // Generate Path
  const ribbonWidth = widthProp + Math.sin(t * 0.5) * 20;

  const d = [
    `M ${topX}, -100`, 
    `C ${cp1x}, ${cp1y} ${cp2x}, ${cp2y} ${bottomX}, ${height + 100}`,
    `L ${bottomX + ribbonWidth}, ${height + 100}`,
    `C ${cp2x + ribbonWidth}, ${cp2y} ${cp1x + ribbonWidth}, ${cp1y} ${topX + ribbonWidth}, -100`,
    `Z`
  ].join(" ");

  return (
    <path
      d={d}
      fill={color}
      style={{
        mixBlendMode: "screen",
        opacity: 0.8,
      }}
    />
  );
};

// 2. Meditating Human Silhouette
